import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Empasy Product Guide","text":"Boon to business by agility.","tagline":"'Solutions Optimized for Change', Maximize business agility with the Sync Series.","actions":[{"text":"Get Started","link":"/syncverse/","type":"primary"},{"text":"View All Products","link":"#sync-series-product-line","type":"secondary"}]},"head":[["meta",{"name":"keywords","content":"Test Automation, Empasy, Sync Series, SyncVerse, SyncInsight, AI Orchestration, Multi-Agent, AI Monitoring, SyncBoot, SyncAdmin, SyncCMS, SyncEta, Microservices Architecture, MSA, Software Development, Solutions, Digital Transformation, Business Agility, Development Platform, Backend, Frontend, Content Management System, CMS, AI Testing, Automated Testing, QA, Quality Assurance, CI/CD, DevOps, Website Building, System Integration, SI, ITO, Customized Solutions, Java, Vue.js, Vue 3, Vite, TypeScript, Freemarker, Selenium"}],["meta",{"property":"og:title","content":"Empasy Sync Series: MSA-based Solutions for Digital Transformation | Development, CMS, AI Test Automation"}],["meta",{"property":"og:description","content":"Empasy maximizes corporate digital transformation and business agility through the Sync Series, consisting of SyncBoot, SyncAdmin, SyncCMS, and SyncEta. Accelerate development, guarantee quality, and reduce maintenance costs with MSA-based backend, frontend, CMS, and AI test automation."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/"}]],"features":[{"title":"Optimization of Business Agility and Change Response","details":"Rapidly supports software changes in response to the fast-paced business environment, helping companies increase agility and maintain competitiveness. The Sync Series focuses on speed and flexibility from development to testing."},{"title":"Development/Operation Efficiency and User Friendliness","details":"With intuitive interfaces and built-in features, developers can focus on core business logic, while non-experts can easily manage content or automate tests."},{"title":"Outstanding Customization and Flexible Expansion","details":"System expansion and modification are possible to suit various business environments and customer requirements, and cost efficiency can be increased by selectively adopting only necessary features."},{"title":"Open-Source Based Vendor Independence","details":"Provides flexibility with open-source-based solutions that are not dependent on specific vendors, making it easy to quickly adopt innovative technologies and advance services."},{"title":"Comprehensive Integrated Management and E2E Solutions","details":"Maximizes work efficiency by integrally managing the entire process from development to operations, including API management, CI/CD, monitoring, and test automation."},{"title":"Securing High Stability, Quality, and Security","details":"A stable solution verified through numerous deployment cases, providing reliable services with continuous monitoring and robust security features."}],"footer":"Copyright © 2025 Empasy"},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":1784590561000}`),a={name:`en/index.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h2 id="empasy-documentation" tabindex="-1">Empasy Documentation <a class="header-anchor" href="#empasy-documentation" aria-label="Permalink to “Empasy Documentation”">​</a></h2><p>Includes the following documents:</p><ul><li><a href="/docs/synceta/">SyncETA</a> - An integrated test automation platform that helps anyone easily build automated tests without coding and integrate them into CI/CD environments to respond quickly and stably to business changes.</li><li><a href="/docs/synccrawl/">SyncCrawl</a> - An intelligent integrated crawling solution that collects web data using natural language commands and builds a RAG knowledge base. It maximizes operational efficiency by automatically responding to web structure changes and provides accurate, highly reliable answers without LLM hallucinations.</li><li><a href="/docs/synccms/">SyncCMS</a> - An efficient content management platform that allows websites to evolve quickly in line with business changes, enables non-experts to easily manage content, and provides flexible feature expansion.</li><li><a href="/docs/syncboot/">SyncBoot</a> - A platform that provides a rapid development and efficient operational environment based on open-source microservices, helping enterprises quickly respond to fast-changing business environments and secure a competitive advantage.</li><li><a href="/docs/syncadmin/">SyncAdmin</a> - An open-source management system template based on Vue 3, Vite, and TypeScript. It maximizes the productivity of mid-to-large back-office development by providing reusable components and a rapid development environment, supporting swift responses to changing requirements.</li><li><a href="/docs/syncapim/">SyncApim</a> - A powerful platform that accelerates digital transformation and strengthens business competitiveness through comprehensive and stable API management and <strong>outstanding customization (Customization in its DNA)</strong>.</li><li><a href="/docs/syncverse/">SyncVerse</a> - An LLM-Native central orchestration platform where multiple specialized AI agents collaborate organically to autonomously manage system infrastructure and business logic.</li><li><a href="/docs/syncinsight/">SyncInsight</a> - An AI-driven intelligent monitoring center that collects and analyzes massive amounts of data across the agent ecosystem in real-time, deriving business insights intuitively through Natural Language Queries (NLQ).</li><li><a href="/docs/agile/">Agile</a> - The Empasy development methodology (Scrumban) that combines Scrum and Kanban for Agile innovation.</li><li><a href="/docs/study/">Study</a> - Empasy Study Room.</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Empasy is a company that develops software solutions to respond agilely to rapidly changing business environments based on the core value of &quot;Empathic Synergy&quot;. Empasy mainly focuses on solution-based System Integration (SI) and IT Outsourcing (ITO) businesses, and specifically supports securing business agility for enterprises through its Sync Series product line, which promotes &quot;Solutions Optimized for Change&quot; as its highest value. The Sync Series aims to increase speed, efficiency, and flexibility across the entire software lifecycle, including development, testing, content management, and API management.</p><h2 id="empasy-s-core-values-and-vision" tabindex="-1">Empasy&#39;s Core Values and Vision <a class="header-anchor" href="#empasy-s-core-values-and-vision" aria-label="Permalink to “Empasy&#39;s Core Values and Vision”">​</a></h2><p>Empasy&#39;s company name, &quot;EmpaSy&quot;, stands for &quot;Empathic Synergy&quot;, which means creating outstanding results through deep empathy and collaboration. This embodies the philosophy of achieving common goals based on deep understanding and support between customers and team members. Recognizing that &quot;rapid response is required in a fast-changing business environment&quot;, Empasy emphasizes that software is at the center of all operations and that rapid software modification is essential to quickly adapt to changing business environments. Accordingly, Empasy developed the Sync Series to efficiently respond to these rapid changes, explicitly stating that &quot;Solutions Optimized for Change&quot; is the highest value of the Sync product line. Furthermore, with the slogan &quot;Boon to business agility&quot;, one of the company&#39;s main goals is &quot;We create living software.&quot;</p><h2 id="sync-series-product-line" tabindex="-1">Sync Series Product Line <a class="header-anchor" href="#sync-series-product-line" aria-label="Permalink to “Sync Series Product Line”">​</a></h2><p>Empasy possesses the Sync Series product line to secure business agility, and the main products are as follows:</p><h3 id="synccms-content-management-system" tabindex="-1">SyncCMS: Content Management System <a class="header-anchor" href="#synccms-content-management-system" aria-label="Permalink to “SyncCMS: Content Management System”">​</a></h3><ol><li>Overview: A CMS designed to easily build websites and management systems.</li><li>Key Features: Java-based stability, providing high stability and scalability.</li><li>Modular Structure: Selective use of features as needed.</li><li>Template Support: Design and layout management through customizable templates.</li><li>Multilingual Support: Easy to build global websites.</li><li>SEO Optimization: Improved search engine visibility.</li><li>User Permission Management: Granular permission settings.</li><li>RESTful API Support: Increased scalability.</li><li>Freemarker-based Template Engine: Guarantees design flexibility.</li><li>Cross-Platform: Can run in various environments.</li><li>Real-time Data Processing: Database change detection and synchronization.</li><li>Advantages: &quot;Even non-developers, like marketers or operations managers, can easily update or fix website content,&quot; and &quot;Thanks to the modular structure, it is much more flexible to add or expand new features when needed.&quot; Scalability, user-friendly interface, and community support. It provides various extension points and a Spring-based web framework to overcome vendor lock-in and customization limits.</li><li>Use Cases: Corporate websites, blogs, news portals, e-commerce platforms, government and public institution portals, rapid prototyping.</li></ol><h3 id="syncboot-java-rapid-development-platform" tabindex="-1">SyncBoot: Java Rapid Development Platform <a class="header-anchor" href="#syncboot-java-rapid-development-platform" aria-label="Permalink to “SyncBoot: Java Rapid Development Platform”">​</a></h3><ol><li>Overview: An open-source rapid development platform based on Java, aimed at streamlining enterprise application development.</li><li>Tech Stack: Backend (Spring Boot, Spring Cloud, MyBatis-Plus, JWT), Frontend (Vue.js, Ant Design Vue, React), Database (MySQL, Oracle, etc.), Modularization (Permission management, Workflow, Reports, Dashboards), Cloud Support (Microservices Architecture).</li><li>Key Features: System management (Users, roles, menus, data permissions), Data visualization (Drag &amp; Drop dashboards, chart reports), Mobile responsiveness, API documentation (Swagger integration).</li><li>Advantages: &quot;Built on top of the stable Java and Spring Boot Framework. It provides pre-built complex modules frequently used in enterprise environments, like permission management and security.&quot; &quot;Developers can spend less time building these basic features and focus more on actual business logic development.&quot; &quot;Because it&#39;s based on standard technologies, it helps developers easily adapt and quickly build enterprise applications.&quot; Low learning curve, active community, scalability.</li><li>Use Cases: SME enterprise applications such as ERP/CRM systems, internal management platforms, data analysis dashboards, etc. Provides expected benefits such as securing an MSA operational environment, service stabilization, open-source foundation, establishing a DevOps dev/ops environment, improving failure response capabilities, and securing an advancement roadmap.</li></ol><h3 id="syncadmin-vue-3-management-system-template" tabindex="-1">SyncAdmin: Vue 3 Management System Template <a class="header-anchor" href="#syncadmin-vue-3-management-system-template" aria-label="Permalink to “SyncAdmin: Vue 3 Management System Template”">​</a></h3><ol><li>Overview: An open-source management system template based on Vue 3, Vite, and TypeScript, optimized for developing mid-to-large back-offices and admin dashboards.</li><li>Key Features: Modern tech stack utilizing Vue 3, Vite, TypeScript, Pinia, Vue Router, etc.</li><li>Multilingual Support: Built-in internationalization (i18n) functionality.</li><li>Permission Management: Granular access control including dynamic routing and button-level control.</li><li>Theme Customization: Support for various themes and dark mode.</li><li>Built-in Mock Server: Provides a high-performance Nitro-based Mock server.</li><li>Various UI Framework Support: Compatible with Ant Design Vue, Naive UI, Element Plus, etc.</li><li>Monorepo Structure: Utilizes Pnpm and TurboRepo.</li><li>Rich Components: Provides reusable components, utilities, and hooks.</li><li>Advantages: Through &quot;reusable components and the Vite build tool&quot;, &quot;even complex management screens can be built quickly, like assembling Lego blocks&quot;, and &quot;changes during development are reflected on the screen almost in real-time. So the development speed itself becomes noticeably faster.&quot;</li><li>Use Cases: Internal enterprise systems (ERP, CRM, etc.), admin dashboards, learning and educational tools.</li></ol><h3 id="sync-apim-api-management-platform" tabindex="-1">Sync APIM: API Management Platform <a class="header-anchor" href="#sync-apim-api-management-platform" aria-label="Permalink to “Sync APIM: API Management Platform”">​</a></h3><ol><li>Overview: An API management platform that leads digital transformation and value creation through APIs. It emphasizes &quot;Customization in its DNA&quot; and provides customer-tailored solutions.</li><li>Key Features: Stability ensuring a highly available and stable operational environment.</li><li>Security: Multi-layered security through OAuth 2.0, JWT, and API keys.</li><li>Integrated Management: Handles API creation, deployment, security, monitoring, and analysis in one place.</li><li>Developer Friendly: Intuitive developer portal and rich documentation.</li><li>Scalability: Cloud-native architecture for handling massive traffic and flexibly responding to diverse environments.</li><li>Policy Management: Provides various policies such as call limits, alerts, statistics, and enables the development of customer-specific policies.</li><li>API Management: Centralized API registration and group classification.</li><li>API Testing: Endpoint invocation and response validation.</li><li>Monitoring: Near real-time tracking and analysis of API performance and status.</li><li>System Alerts: Provides administrator alerts when critical events occur.</li><li>Advantages: Business expansion (partnerships and developer ecosystem building), Security enhancement (data encryption, unauthorized access prevention), API performance optimization (improved response speed), Cost reduction (API lifecycle automation, reduced development time), Improved operational efficiency, API-centric ecosystem building, Business model expansion, Strengthened corporate competitiveness. Provides flexible customization, cost efficiency, rapid deployment, and high satisfaction through customer-tailored systems.</li><li>Expected Benefits: Automation of the API management process, strengthened collaboration between internal and external developers, development and monetization of new API services, provision of innovative API-based services and market leadership.</li></ol><h3 id="synceta-web-test-automation-platform" tabindex="-1">SyncETA: Web Test Automation Platform <a class="header-anchor" href="#synceta-web-test-automation-platform" aria-label="Permalink to “SyncETA: Web Test Automation Platform”">​</a></h3><ol><li>Overview: An integrated test automation platform that supports web automated testing, built on top of a Selenium-based engine.</li><li>Key Features: Diverse test support including web, mobile, and API testing.</li><li>Dual Interface: Provides script-based (Groovy/Java) and keyword/GUI-based codeless modes.</li><li>Automation Tools: Test Recording, Object Spy, debugging, data-driven testing.</li><li>Integrated Management: Management of test cases, suites, and execution results.</li><li>CI/CD Integration: Integration with Jenkins, Azure DevOps, Git, Slack, etc.</li><li>Story-based Testing: Dynamic execution by connecting scenarios with Flow Charts.</li><li>Real-time Communication and AI Screen Validation: Socket communication and data validation using AI.</li><li>AI Test Data Auto-generation and Management: Automatic generation of mockup data.</li><li>Dynamic Test CHAINING: Sequential scenario execution based on conditions.</li><li>Advantages: &quot;Making quick changes naturally increases the chance of errors. SyncEta solves exactly that.&quot; &quot;Simply put, it automatically scripts user actions on a website and runs tests automatically.&quot; &quot;It provides a user-friendly development environment, an IDE, allowing highly efficient management from test creation to execution and result reporting.&quot; &quot;What&#39;s especially important is that it integrates with CI/CD, i.e., continuous integration and deployment tools. When a developer changes code, it automatically connects testing and deployment, allowing software changes to be reflected really quickly and stably.&quot; User-friendliness (easy even for users with little coding experience), diverse test type support, initial cost reduction and maintenance cost minimization, efficient resource management, strengthened collaboration, speed improvement and test scalability securing, sustainable quality management, customer satisfaction improvement. Provides an easy and rapid codeless web test automation environment.</li><li>Use Cases: Reduced time-to-market through automated testing, CI/CD and external system integration, strengthened test quality and reliability, improved test management and execution efficiency.</li></ol><h3 id="syncverse-intelligent-multi-agent-orchestration" tabindex="-1">SyncVerse: Intelligent Multi-Agent Orchestration <a class="header-anchor" href="#syncverse-intelligent-multi-agent-orchestration" aria-label="Permalink to “SyncVerse: Intelligent Multi-Agent Orchestration”">​</a></h3><ol><li>Overview: A central control platform that connects individually operating software modules into a single, organic AI ecosystem.</li><li>Key Features: LLM-centric system operation, Agent-to-Agent (A2A) communication network establishment, natural language-based conversational operational control support.</li><li>Advantages: Agents proactively propose and execute system changes, allowing developers to focus on decision-making rather than infrastructure expansion. It perfectly maintains corporate security in a private AI environment.</li></ol><h3 id="syncinsight-ai-driven-intelligent-data-monitoring-center" tabindex="-1">SyncInsight: AI-Driven Intelligent Data Monitoring Center <a class="header-anchor" href="#syncinsight-ai-driven-intelligent-data-monitoring-center" aria-label="Permalink to “SyncInsight: AI-Driven Intelligent Data Monitoring Center”">​</a></h3><ol><li>Overview: A monitoring platform that integrally collects scattered data inside and outside the system, which AI analyzes in real-time to assist in business decision-making.</li><li>Key Features: Real-time data streaming analysis, autonomous anomaly detection, customized chart generation based on Natural Language Queries (NLQ).</li><li>Advantages: Even without complex query or dashboard design knowledge, users can gain insights with everyday questions, and AI proactively suggests optimal resolution actions for problematic situations.</li></ol><h2 id="empasy-s-business-areas-and-competitiveness" tabindex="-1">Empasy&#39;s Business Areas and Competitiveness <a class="header-anchor" href="#empasy-s-business-areas-and-competitiveness" aria-label="Permalink to “Empasy&#39;s Business Areas and Competitiveness”">​</a></h2><p>Empasy focuses on System Integration (SI), IT Outsourcing (ITO), Solution Business, and Mobile Business. In particular, it provides optimal services to customers through its internally developed SyncCMS and SyncBoot solutions. Core Competitiveness Points: Efficient collaboration capabilities based on advanced technology, experience in building optimal IT systems tailored to the business environment requirements of various industries, performing ITO projects as a strategic business partner for large and mid-sized enterprises, a flexible system building platform based on microservices (SyncBoot), a systematic content management and scalable web service development platform (SyncCMS), and capabilities ranging from mobile app development to system integration and providing operational environments.</p><h2 id="deployment-cases" tabindex="-1">Deployment Cases <a class="header-anchor" href="#deployment-cases" aria-label="Permalink to “Deployment Cases”">​</a></h2><p>Empasy holds successful deployment cases utilizing Sync Series products for various clients. Key cases are as follows:</p><ol><li>Homeplus MIS System Rebuild (SyncBoot)</li><li>SK Magic MagicPlus BO Revamp Project (SyncBoot)</li><li>Samsung DS Brand Desk Site Construction (SyncCMS)</li><li>KT ESG Portal Site Construction (SyncCMS)</li><li>LX Hausys Overseas Global Website Construction and Maintenance (SyncCMS)</li><li>SK Magic e-Catalog System Construction (SyncCMS)</li><li>Chunjae Education T-Selpa Renewal Construction (SyncCMS)</li><li>Visang Education AIDT (SyncEta)</li><li>LG Electronics Portal (SyncEta)</li><li>Hyundai Motor Company Log Collection (SyncEta)</li><li>Penta Security (SyncApim)</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to “Conclusion”">​</a></h2><p>Empasy&#39;s Sync Series product line focuses on supporting enterprises to respond agilely and secure competitiveness in rapidly changing business environments. Each product possesses technical features and advantages that provide speed, efficiency, and flexibility in core areas of the software lifecycle, such as frontend development, backend development, content management, test automation, and API management. Empasy&#39;s philosophy of &quot;Solutions Optimized for Change&quot; is implemented across the entire Sync Series product line, contributing to the business success of customers based on proven technology and rich deployment experience. Beyond a simple list of features, the Sync Series is a solution that contains Empasy&#39;s deep thoughts and answers to solving the difficult task of corporate change management.</p>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};